-- Baseline migration: captures the schema exactly as it existed when Flyway was introduced
-- (previously managed by Hibernate's ddl-auto: update). Generated from a schema-only pg_dump
-- of the dev database, not hand-written from entity annotations, so it's byte-faithful to
-- what Hibernate actually created — including its auto-generated constraint names.
--
-- This migration is never run against the database it was captured from: see
-- spring.flyway.baseline-on-migrate / baseline-version in application.yml, which tell Flyway
-- to treat that database as already being at this version. It exists so a *fresh* database
-- (a new environment, a teammate's machine, production) can be brought to the same schema
-- from nothing, and so every schema change from here on is a new versioned migration file
-- instead of Hibernate silently altering a live database.

CREATE TABLE public.ai_usage_log (
    id bigint NOT NULL,
    count integer NOT NULL,
    date date NOT NULL,
    user_id bigint NOT NULL
);

ALTER TABLE public.ai_usage_log ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.ai_usage_log_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.attendance (
    id bigint NOT NULL,
    date date NOT NULL,
    status character varying(255) NOT NULL,
    student_id bigint NOT NULL,
    CONSTRAINT attendance_status_check CHECK (((status)::text = ANY ((ARRAY['PRESENT'::character varying, 'ABSENT'::character varying, 'LATE'::character varying])::text[])))
);

ALTER TABLE public.attendance ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.attendance_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.exams (
    id bigint NOT NULL,
    exam_date date NOT NULL,
    max_marks double precision NOT NULL,
    name character varying(255) NOT NULL,
    school_class_id bigint NOT NULL,
    subject_id bigint NOT NULL
);

ALTER TABLE public.exams ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.exams_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.marks (
    id bigint NOT NULL,
    marks_obtained double precision NOT NULL,
    exam_id bigint NOT NULL,
    student_id bigint NOT NULL
);

ALTER TABLE public.marks ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.marks_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.resource_views (
    id bigint NOT NULL,
    first_viewed_at timestamp(6) without time zone NOT NULL,
    last_viewed_at timestamp(6) without time zone NOT NULL,
    view_count integer NOT NULL,
    resource_id bigint NOT NULL,
    user_id bigint NOT NULL
);

ALTER TABLE public.resource_views ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.resource_views_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.resources (
    id bigint NOT NULL,
    body text NOT NULL,
    created_at timestamp(6) without time zone,
    external_url character varying(255),
    summary character varying(255) NOT NULL,
    title character varying(255) NOT NULL,
    type character varying(255) NOT NULL,
    author_id bigint NOT NULL,
    status character varying(255) NOT NULL,
    review_note character varying(255),
    CONSTRAINT resources_status_check CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PENDING_REVIEW'::character varying, 'PUBLISHED'::character varying, 'REJECTED'::character varying])::text[]))),
    CONSTRAINT resources_type_check CHECK (((type)::text = ANY ((ARRAY['ARTICLE'::character varying, 'VIDEO'::character varying, 'PROBLEM_SET'::character varying, 'COURSE'::character varying])::text[])))
);

ALTER TABLE public.resources ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.resources_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.school_classes (
